-- Jalankan satu kali setelah riwayat pembayaran Bali/Bandung dan simulasi demo tersedia.
-- Kolom pembatalan mempertahankan transaksi sebagai jejak audit.
SET @ddl = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='nusa_karsa' AND TABLE_NAME='payments' AND COLUMN_NAME='cancelled_at')=0, 'ALTER TABLE nusa_karsa.payments ADD COLUMN cancelled_at DATETIME NULL, ADD COLUMN cancelled_by INT UNSIGNED NULL, ADD COLUMN cancellation_reason VARCHAR(255) NULL', 'SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='nusa_karsa' AND TABLE_NAME='palembang_payments' AND COLUMN_NAME='cancelled_at')=0, 'ALTER TABLE nusa_karsa.palembang_payments ADD COLUMN cancelled_at DATETIME NULL, ADD COLUMN cancelled_by INT UNSIGNED NULL, ADD COLUMN cancellation_reason VARCHAR(255) NULL', 'SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='events_bali' AND TABLE_NAME='event_payments' AND COLUMN_NAME='cancelled_at')=0, 'ALTER TABLE events_bali.event_payments ADD COLUMN cancelled_at DATETIME NULL, ADD COLUMN cancelled_by INT UNSIGNED NULL, ADD COLUMN cancellation_reason VARCHAR(255) NULL', 'SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='events_bandung' AND TABLE_NAME='event_payments' AND COLUMN_NAME='cancelled_at')=0, 'ALTER TABLE events_bandung.event_payments ADD COLUMN cancelled_at DATETIME NULL, ADD COLUMN cancelled_by INT UNSIGNED NULL, ADD COLUMN cancellation_reason VARCHAR(255) NULL', 'SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='nusa_karsa' AND TABLE_NAME='payments' AND COLUMN_NAME='cancelled_by_role')=0, 'ALTER TABLE nusa_karsa.payments ADD COLUMN cancelled_by_role VARCHAR(24) NULL AFTER cancelled_by', 'SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='nusa_karsa' AND TABLE_NAME='palembang_payments' AND COLUMN_NAME='cancelled_by_role')=0, 'ALTER TABLE nusa_karsa.palembang_payments ADD COLUMN cancelled_by_role VARCHAR(24) NULL AFTER cancelled_by', 'SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='events_bali' AND TABLE_NAME='event_payments' AND COLUMN_NAME='cancelled_by_role')=0, 'ALTER TABLE events_bali.event_payments ADD COLUMN cancelled_by_role VARCHAR(24) NULL AFTER cancelled_by', 'SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @ddl = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='events_bandung' AND TABLE_NAME='event_payments' AND COLUMN_NAME='cancelled_by_role')=0, 'ALTER TABLE events_bandung.event_payments ADD COLUMN cancelled_by_role VARCHAR(24) NULL AFTER cancelled_by', 'SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;